create table if not exists public.customers(customer_id bigint generated always as identity primary key,customer_number text not null unique,company_name text not null,tax_id text not null,primary_subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),currency_id bigint not null references public.currencies(currency_id),payment_term_id bigint references public.payment_terms(term_id),credit_limit numeric(24,6) not null default 0 check(credit_limit>=0));
create table if not exists public.suppliers(supplier_id bigint generated always as identity primary key,supplier_number text not null unique,company_name text not null,tax_id text not null,primary_subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),currency_id bigint not null references public.currencies(currency_id),payment_term_id bigint references public.payment_terms(term_id));
create table if not exists public.entity_subsidiaries(id bigint generated always as identity primary key,customer_id bigint references public.customers(customer_id) on delete cascade,supplier_id bigint references public.suppliers(supplier_id) on delete cascade,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id) on delete cascade,is_primary boolean not null default false,credit_limit numeric(24,6) not null default 0 check(credit_limit>=0),check((customer_id is not null)::integer+(supplier_id is not null)::integer=1));
create unique index if not exists entity_subsidiary_customer_uidx on public.entity_subsidiaries(customer_id,subsidiary_id) where customer_id is not null;create unique index if not exists entity_subsidiary_supplier_uidx on public.entity_subsidiaries(supplier_id,subsidiary_id) where supplier_id is not null;
create table if not exists public.employees(employee_id bigint generated always as identity primary key,employee_number text not null unique,first_name text not null,last_name text not null,subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),department_id bigint references public.departments(department_id),location_id bigint references public.locations(location_id),user_id bigint references public.users(user_id),is_active boolean not null default true);
do $$declare t text;begin foreach t in array array['customers','suppliers','entity_subsidiaries','employees']loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "entity_select" on public.%I',t);execute format('drop policy if exists "entity_insert" on public.%I',t);execute format('drop policy if exists "entity_update" on public.%I',t);execute format('drop policy if exists "entity_delete" on public.%I',t);execute format('create policy "entity_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "entity_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "entity_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "entity_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
